const l=(tr,en,es)=>[tr,en,es];
const tourism=l('Experience Egypt — resmî turizm','Experience Egypt — official tourism','Experience Egypt — turismo oficial');
export const cities=[{
 code:'EG',name:l('Kahire','Cairo','El Cairo'),image:'/images/added-kahire.avif',card:l('Giza Piramitleri, tarihî merkez, müzeler ve Nil mahalleleriyle büyük bir şehir ve arkeoloji gezisi.','Giza’s pyramids, historic lanes, museums and Nile neighbourhoods make a layered city and archaeology trip.','Pirámides de Guiza, calles históricas, museos y barrios del Nilo para combinar ciudad y arqueología.'),title:l('Kahire Gezi Rehberi: Piramitler, Müzeler ve 3 Günlük Rota','Cairo Travel Guide: Pyramids, Museums and a 3-Day Route','Qué ver en El Cairo: pirámides, museos y ruta de 3 días'),meta:l('Kahire gezi rehberi: Giza Piramitleri, Büyük Mısır Müzesi, Han el-Halili ve Nil mahalleleri; ulaşım, nerede kalınır ve 3 günlük rota planı.','Explore Cairo and Giza: pyramids, the Grand Egyptian Museum, Khan el-Khalili and Nile neighbourhoods, with transport, stays and a 3-day route.','Qué ver en El Cairo y Guiza: pirámides, Gran Museo Egipcio, Jan el-Jalili y barrios del Nilo, con transporte, alojamiento y una ruta de 3 días.'),lede:l('Kahire yalnız piramitlere gidilen bir aktarma noktası değildir. Giza’nın arkeoloji günü, tarihî merkezin yürüyüşleri ve Nil kıyısındaki çağdaş mahalleler için ayrı zaman ayırmak hem yoğunluğu yönetir hem şehri daha iyi tanıtır.','Cairo is more than a gateway to the pyramids. Separate Giza’s archaeology, the historic centre and contemporary Nile neighbourhoods into distinct days to manage distances and experience the city beyond its headline monuments.','El Cairo merece más que servir de paso hacia las pirámides. Separa la arqueología de Guiza, el centro histórico y los barrios del Nilo para gestionar distancias y conocer la ciudad que rodea sus monumentos.'),days:l('3–4 tam gün','3–4 full days','3–4 días completos'),time:l('Ekim–Nisan','October–April','Octubre–abril'),transport:l('Metro ve bölge bazlı araç bağlantısı','Metro and area-based car transfers','Metro y traslados por zonas'),arrival:l('Cairo International (CAI) ile Sphinx International (SPX) farklı havalimanlarıdır. Oteliniz Giza’da veya Nil’in doğusunda olduğunda transfer süreleri değişir. Terminal, karşılama noktası ve fiyatı yazılı teyit edin; trafik payını varış gününün biletli programına ekleyin.','Cairo International (CAI) and Sphinx International (SPX) are different airports. Transfers vary between Giza and the east bank of the Nile. Confirm the terminal, meeting point and price, and leave traffic buffer before any booked arrival-day visit.','Cairo International (CAI) y Sphinx International (SPX) son distintos. Los traslados cambian entre Guiza y la orilla oriental del Nilo. Confirma terminal, encuentro y precio, y deja margen por tráfico antes de visitas reservadas.'),movement:l('Metro bazı merkez bağlantılarında işe yarar; Giza platosu ve dağınık anıtlar için son bağlantı gerekir. Bir günü Nil’in batısına, diğerini tarihî merkeze ayırmak köprü trafiğini azaltır. Uygulamalı araçta plaka ve buluşma noktasını doğrulayın.','The metro helps with some central journeys, but Giza’s plateau and scattered monuments need onward transfers. Keeping one day west of the Nile and another in the historic centre reduces repeated bridge crossings. Verify your vehicle and pickup point.','El metro ayuda en conexiones céntricas, pero la meseta de Guiza y monumentos dispersos necesitan otro tramo. Separa una jornada al oeste del Nilo y otra al centro histórico para evitar cruces repetidos.'),overview:l('Giza’yı sabah, büyük müzeyi ayrı bir geniş zaman bloğunda görün. Tarihî Kahire’de Han el-Halili ile El Muizz çevresini yürüyüşe bağlayın; Nil mahallelerini farklı bir akşam molası yapın.','Visit Giza early and leave a generous separate block for the museum. Pair Khan el-Khalili with an Al-Muizz walk, then use the Nile neighbourhoods for a different evening.','Visita Guiza temprano y reserva un bloque amplio para el museo. Combina Jan el-Jalili con Al-Muizz y dedica otra tarde a los barrios del Nilo.'),sights:[
 {name:l('Giza Piramitleri ve Sfenks','Giza Pyramids and the Sphinx','Pirámides de Guiza y la Esfinge'),area:l('Giza platosu','Giza Plateau','Meseta de Guiza'),known:l('Piramit kompleksi','Pyramid complex','Complejo de pirámides'),reason:l('Anıtları tek kare yerine bütün bir alan olarak görmek için.','To explore the monuments as a whole landscape.','Para recorrer los monumentos como un conjunto.'),tip:l('Piramit içi girişin genel bilete dahil olduğunu varsaymayın.','Do not assume pyramid interiors are included in general admission.','No presupongas que la entrada general incluye interiores.'),body:l('Plato geniş ve açık alandır; sabah başlayıp su ve gölge molasını planlayın. Anıt içi erişim, taşıma ve rehberlik genel alan biletiyle aynı hizmet değildir. Deveyi veya özel turu kabul etmeden güzergâh, süre ve toplam bedeli netleştirin.','The plateau is extensive and exposed: start early and plan water and shade breaks. Interior admission, transport and guiding are separate considerations. Agree route, duration and total price before taking a camel ride or private tour.','La meseta es amplia y expuesta: empieza temprano y prevé agua y sombra. Interiores, transporte y guía son conceptos distintos. Acuerda recorrido, duración y precio total antes de aceptar paseo en camello o visita privada.')},
 {name:l('Büyük Mısır Müzesi','Grand Egyptian Museum','Gran Museo Egipcio'),area:l('Giza','Giza','Guiza'),known:l('Müze koleksiyonları ve büyük sergi alanları','Museum collections and spacious galleries','Colecciones y grandes salas'),reason:l('Antik eserleri bağlamıyla incelemek için.','To explore antiquities with their context.','Para conocer las piezas en su contexto.'),tip:l('Güncel galeri kapsamını ve bilet türünü kontrol edin.','Check current gallery coverage and ticket categories.','Consulta salas incluidas y tipos de entrada actuales.'),body:l('Müzeyi Giza ziyaretinin kısa son durağına çevirmeyin. Güncel açık galerileri, saatli bilet kapsamını ve ulaşımı resmî kanaldan kontrol ederek en az bir uzun yarım gün bırakın. Fotoğraf, çanta ve yiyecek koşulları için ziyaretçi bilgisini okuyun.','Do not reduce the museum to a brief add-on after Giza. Check currently accessible galleries, ticket coverage and transport through official channels, and reserve a long half-day. Read visitor guidance for bags, photography and food.','No lo conviertas en una parada breve después de Guiza. Consulta galerías accesibles, entrada y transporte en canales oficiales, y reserva medio día largo. Revisa normas sobre bolsas, fotografía y comida.')},
 {name:l('Han el-Halili ve El Muizz','Khan el-Khalili and Al-Muizz','Jan el-Jalili y Al-Muizz'),area:l('Tarihî Kahire','Historic Cairo','El Cairo histórico'),known:l('Çarşı ve anıt sokakları','Bazaar and monument-lined lanes','Zoco y calles monumentales'),reason:l('Yaşayan şehir dokusunu yürüyerek görmek için.','For a walk through the living historic city.','Para pasear por el centro histórico vivo.'),tip:l('İbadet yerlerinde ziyaretçi girişini ve kıyafeti kontrol edin.','Check visitor access and clothing at religious sites.','Consulta acceso y vestimenta en lugares de culto.'),body:l('Çarşıyı El Muizz’in anıtlarıyla bir yürüyüş eksenine bağlayın; bütün yapılar aynı giriş biletiyle ziyaret edilmez. Alışverişte malzeme ve fiyatı baştan konuşun. Dar sokaklardan sonra Nil kıyısındaki sakin bir yemek molası günün temposunu dengeler.','Connect the bazaar with Al-Muizz’s monuments, whose admissions can be separate. Agree material and price when shopping, then balance the busy lanes with a quieter meal by the Nile.','Enlaza el zoco con los monumentos de Al-Muizz, que pueden tener entradas independientes. Aclara material y precio al comprar y compensa las calles concurridas con una comida tranquila junto al Nilo.')}
 ],stay:l('Downtown merkez yürüyüşleri ve metro, Zamalek Nil adasında daha sakin bir üs, Giza ise piramit ve müze önceliği için uygundur. “Piramit manzaralı” odanın gerçek pencere yönünü, çevre yürünebilirliğini ve şehir merkezine günlük transferini kontrol edin.','Downtown suits central walks and metro access, Zamalek offers an island base, and Giza suits pyramid and museum priorities. For a “pyramid-view” room, verify the actual view, walkability and cost of daily transfers into Cairo.','Downtown conviene para centro y metro; Zamalek para una base en la isla del Nilo; Guiza para pirámides y museo. Comprueba vistas reales, entorno y traslados diarios de una habitación “con vistas a las pirámides”.'),food:l('Koşeri, ful medames ve taameya gündelik mutfağa iyi girişlerdir; molokhiya ve ızgaralarda tarif ile et suyunu sorun. Yoğun ziyarette gün boyu ağır öğünler yerine sabah anıt, öğlen kapalı mekân ve akşam yemek ritmi daha rahattır.','Koshary, ful medames and taameya are approachable everyday dishes. Ask about stock and ingredients in molokhia and grilled meals. Pair early monuments with an indoor midday break and a more leisurely dinner.','Koshari, ful medames y taameya son buenas introducciones cotidianas. Pregunta por caldo e ingredientes en molokhiya y platos de parrilla. Combina monumentos temprano, descanso al mediodía y cena tranquila.'),season:l('Ekim–nisan açık alanlar için daha rahattır. Yazın piramitleri erken, müzeleri sıcak saatlerde planlayın. Trafik ve ziyaretçi yoğunluğu yıl boyunca değişir; kısa takvimde her güne iki ana bölgeden fazlasını koymayın.','October to April is easier for exposed sites. In summer, visit pyramids early and museums in hotter hours. Traffic and crowds vary year-round; limit each day to one or two main geographical areas.','De octubre a abril resultan más cómodos los exteriores. En verano, pirámides temprano y museos en las horas cálidas. Tráfico y afluencia varían; limita cada jornada a una o dos zonas.'),budget:l('Anıt biletleri, özel mezar veya piramit girişleri, rehber ve transferi ayrı kalem sayın. Kahire’nin yerel yemek maliyeti turistik paketle aynı değildir. Fiyatı para birimi, kişi sayısı ve dahil hizmetlerle birlikte karşılaştırın.','Separate site admission, special interiors, guides and transfers in your budget. Local meals and tourist packages have different price structures; compare currency, group size and inclusions together.','Presupuesta aparte entradas, interiores especiales, guías y traslados. Comida local y paquetes turísticos tienen precios distintos: compara moneda, número de personas y servicios incluidos.'),beyond:l('Luksor’a devam ediyorsanız uçuş veya tren seçeneğini gerçek saatleriyle kontrol edin; transfer günü bir tam gezi günü değildir. Saqqara’yı eklemek istiyorsanız Giza platosu ve büyük müzeyle aynı kısa güne sıkıştırmayın.','For Luxor, compare flights and trains using actual schedules; a travel day is not a full sightseeing day. If adding Saqqara, give it more time than a brief detour between Giza and the museum.','Para continuar a Luxor compara horarios reales de avión y tren. Un traslado no es un día completo de visitas. Si añades Saqqara, no la comprimas entre Guiza y el gran museo.'),itinerary:[[l('1. Gün — Giza','Day 1 — Giza','Día 1 — Guiza'),l('Piramitler ve Sfenks','Pyramids and the Sphinx','Pirámides y Esfinge'),l('Giza’da yemek ve dinlenme','Meal and rest in Giza','Comida y descanso en Guiza'),l('Otele dönüş ve sakin akşam','Return to the hotel for a quiet evening','Regreso al hotel y tarde tranquila')],[l('2. Gün — Müze ve Nil','Day 2 — Museum and Nile','Día 2 — Museo y Nilo'),l('Büyük Mısır Müzesi','Grand Egyptian Museum','Gran Museo Egipcio'),l('Galeri ziyareti ve transfer','Galleries and transfer','Galerías y traslado'),l('Zamalek veya Nil kıyısında yemek','Dinner in Zamalek or by the Nile','Cena en Zamalek o junto al Nilo')],[l('3. Gün — Tarihî merkez','Day 3 — Historic centre','Día 3 — Centro histórico'),l('El Muizz çevresinde yürüyüş','Al-Muizz area walk','Paseo por Al-Muizz'),l('Han el-Halili ve bir anıt ziyareti','Khan el-Khalili and one monument','Jan el-Jalili y un monumento'),l('Downtown’da yemek molası','Dinner break in Downtown','Cena en Downtown')]],tips:[[l('Giza ayrı bölgedir','Giza is a separate area','Guiza es una zona propia'),l('Giza gününden önce otel ve müze konumlarını haritada işaretleyin; Nil köprülerinde trafik payı bırakın.','Mark your hotel and museum locations before the Giza day, allowing for Nile bridge traffic.','Localiza hotel y museo antes del día de Guiza y deja margen por tráfico en los puentes del Nilo.')],[l('Ek hizmeti baştan sorun','Clarify extras beforehand','Aclara extras antes'),l('Genel biletin rehber, anıt içi veya araç hizmetini kapsadığını varsaymayın.','Do not assume general admission includes guiding, monument interiors or transport.','No presupongas que la entrada incluye guía, interiores o transporte.')]],faqs:[[l('Kahire kaç günde gezilir?','How many days do you need in Cairo?','¿Cuántos días hacen falta en El Cairo?'),l('Giza, müze ve tarihî merkez için üç tam gün; Saqqara ve daha sakin mahalle gezileri için dört veya beş gün.','Three full days cover Giza, the museum and historic centre; allow four or five for Saqqara and slower neighbourhood visits.','Tres días completos para Guiza, museo y centro histórico; cuatro o cinco con Saqqara y barrios sin prisas.')],[l('Kahire’de Giza’da mı merkezde mi kalmalı?','Should you stay in Giza or central Cairo?','¿Dormir en Guiza o en el centro de El Cairo?'),l('Piramit ve müze ağırlıklı kısa gezide Giza, farklı şehir günleri için Downtown veya Zamalek daha dengelidir; transferleri karşılaştırın.','Giza suits a pyramid-and-museum visit; Downtown or Zamalek balance a broader city stay. Compare your planned transfers.','Guiza funciona para pirámides y museo; Downtown o Zamalek equilibran una visita urbana más amplia. Compara los traslados previstos.')],[l('Kahire ve piramitler aynı yerde mi?','Are Cairo and the pyramids in the same area?','¿El Cairo y las pirámides están en la misma zona?'),l('Piramitler Giza’dadır; büyük metropolün parçasıdır ama tarihî merkeze yürüyüş mesafesinde değildir. Ulaşım ve trafik için ayrı zaman gerekir.','The pyramids are in Giza, within the wider metropolis but not walking distance from the historic centre. Allow separate transport and traffic time.','Están en Guiza, dentro de la gran área metropolitana, pero no a pie del centro histórico. Reserva tiempo de transporte y tráfico.')]],diet:l('Koşeri, ful ve taameya bitki bazlı hazırlanabilir; sos, yağ, ekleme ve ortak pişirmeyi kontrol edin. Helal tercihte et kaynağını işletmeden teyit edin; yalnız yerel mutfak adı sertifika kanıtı değildir. Yeterli doğrulama olmadan restoran kartı eklenmiyor.','Koshary, ful and taameya can be plant-based; check sauces, fats, toppings and shared cooking. Confirm meat sourcing for halal preferences; local cuisine is not certification. No restaurant card is added without adequate verification.','Koshari, ful y taameya pueden ser vegetales; comprueba salsas, grasas, añadidos y cocina compartida. Para halal confirma procedencia de la carne; cocina local no equivale a certificación. No se añaden restaurantes sin verificar.'),sources:[[tourism,'https://www.experienceegypt.eg/en/city/1/cairo-e-giza'],[l('Büyük Mısır Müzesi — ziyaret planı','Grand Egyptian Museum — plan your visit','Gran Museo Egipcio — planifica tu visita'),'https://visit-gem.com/'],[l('UNESCO — Tarihî Kahire','UNESCO — Historic Cairo','UNESCO — El Cairo histórico'),'https://whc.unesco.org/en/list/89/'],[l('UNESCO — Memphis ve nekropolü','UNESCO — Memphis and its Necropolis','UNESCO — Menfis y su necrópolis'),'https://whc.unesco.org/en/list/86/']]
},
{
 code:'EG',name:l('Luksor','Luxor','Luxor'),image:'/images/added-luksor.avif',card:l('Karnak, Luksor Tapınağı, Krallar Vadisi ve Hatşepsut arasında Nil’in iki yakasında anıt rotası.','Karnak, Luxor Temple, the Valley of the Kings and Hatshepsut form a monument route on both Nile banks.','Karnak, templo de Luxor, Valle de los Reyes y Hatshepsut en una ruta por ambas orillas del Nilo.'),title:l('Luksor Gezi Rehberi: Karnak ve Krallar Vadisi Rotası','Luxor Travel Guide: Karnak and Valley of the Kings','Qué ver en Luxor: Karnak, tumbas y ruta de 2 días'),meta:l('Luksor gezi rehberi: Karnak, Luksor Tapınağı, Krallar Vadisi ve Hatşepsut; Nil’in iki yakası için ulaşım, bilet ipuçları ve 2 günlük rota.','Visit Luxor’s Karnak, Luxor Temple, Valley of the Kings and Hatshepsut with two-bank transport advice, ticket tips and a focused 2-day itinerary.','Qué ver en Luxor: Karnak, templo de Luxor, Valle de los Reyes y Hatshepsut, con transporte entre orillas, entradas y una ruta práctica de 2 días.'),lede:l('Luksor’da Nil yalnız manzara değil rota sınırıdır. Doğu yakasındaki tapınaklarla batıdaki mezar ve teraslı tapınakları ayrı günlere ayırın; sıcaklık ve bilet kapsamı geziyi anıt sayısından daha fazla belirler.','In Luxor, the Nile shapes the itinerary as much as the view. Give the east-bank temples and west-bank tombs separate days; heat and admission coverage matter more than ticking off the greatest number of monuments.','En Luxor, el Nilo organiza la ruta. Dedica jornadas distintas a templos orientales y tumbas occidentales; calor y condiciones de entrada importan más que sumar monumentos.'),days:l('2–3 tam gün','2–3 full days','2–3 días completos'),time:l('Ekim–Nisan','October–April','Octubre–abril'),transport:l('Yaka bazlı yürüyüş ve araç','Walking and car transfers by riverbank','Paseos y vehículo por orillas'),arrival:l('Luxor International (LXR) transferini otelinizin Nil’in hangi yakasında olduğuna göre ayarlayın. Kahire’den tren veya uçuş, Hurgada’dan karayolu seçeneklerini gerçek seferle karşılaştırın; gece yolculuğundan sonra yoğun mezar günü planlamayın.','Match your Luxor International (LXR) transfer to your hotel’s riverbank. Compare current trains or flights from Cairo and road transfers from Hurghada, avoiding a packed tomb itinerary immediately after overnight travel.','Organiza el traslado desde Luxor International (LXR) según la orilla de tu hotel. Compara tren o vuelo desde El Cairo y carretera desde Hurghada; evita un intenso día de tumbas tras viajar de noche.'),movement:l('Doğu merkezinde bazı duraklar yürünebilir; Karnak ve batı yaka için araç planı gerekir. Nil’i feribotla geçmek anıtlara kadar tüm ulaşımı çözmez. Özel araçta ziyaret sırası, bekleme, dönüş ve ücret kapsamını baştan yazılı netleştirin.','Some east-bank central sights are walkable; Karnak and the west bank need onward transport. A ferry crossing does not take you all the way to the tombs. Confirm stop order, waiting time, return and inclusions for private transfers.','Algunas visitas del centro oriental se hacen a pie, pero Karnak y la orilla oeste necesitan transporte adicional. Cruzar en ferry no te deja en las tumbas. Acuerda paradas, esperas, regreso y precio.'),overview:l('Batı yakasına erken başlayın, doğu tapınaklarını başka güne alın. Her mezara girmek yerine bilet kapsamındaki seçenekleri ilgilerinize göre seçmek ve bir müze molası bırakmak daha dengeli olur.','Start the west bank early and leave the eastern temples for another day. Choose tombs by your interests and ticket coverage, with a museum break instead of rushing into every chamber.','Empieza temprano en la orilla oeste y deja los templos orientales para otro día. Elige tumbas según interés y entrada; añade descanso de museo en vez de entrar en todas.'),sights:[
 {name:l('Karnak Tapınak Kompleksi','Karnak Temple Complex','Complejo de templos de Karnak'),area:l('Doğu yaka','East bank','Orilla oriental'),known:l('Sütunlu salonlar ve tapınak avluları','Columned halls and temple courts','Salas de columnas y patios'),reason:l('Büyük tapınak ölçeğini anlamak için.','For the scale of a major temple complex.','Para comprender la escala del gran complejo.'),tip:l('Su taşıyın ve geniş alana yeterli süre bırakın.','Carry water and allow time for the extensive site.','Lleva agua y tiempo para un recinto amplio.'),body:l('Karnak bir tek yapı değil, avlu ve kutsal alanlardan oluşan geniş komplekstir. Büyük sütunlu salonu gördükten sonra daha sakin bölümlere ilerleyin; yalnız ana fotoğraf noktasında durmayın. Alanın açıklığı nedeniyle erken saat ve gölge molası önemlidir.','Karnak is a complex of courts and sacred spaces, not a single building. Continue beyond the main hypostyle hall into quieter sections. Its exposed scale makes an early start and shade breaks worthwhile.','Karnak reúne patios y espacios sagrados, no un solo edificio. Sigue más allá de la gran sala hipóstila hacia zonas tranquilas. Su extensión expuesta aconseja empezar temprano y buscar descansos con sombra.')},
 {name:l('Krallar Vadisi','Valley of the Kings','Valle de los Reyes'),area:l('Batı yaka','West bank','Orilla occidental'),known:l('Kraliyet mezarları','Royal tombs','Tumbas reales'),reason:l('Duvar resimlerini ve mezar mimarisini görmek için.','For tomb architecture and wall paintings.','Para conocer arquitectura funeraria y pinturas.'),tip:l('Genel bilet ve özel mezar girişlerini ayırın.','Distinguish general admission from special tomb tickets.','Distingue entrada general y tumbas especiales.'),body:l('Açık mezarlar ve genel bilete dahil seçenekler değişebilir; girişte güncel kapsamı okuyun. Özel mezarı ayrıca bütçeleyin. İçeride sıcaklık, kalabalık ve dar geçitler nedeniyle az sayıda mezarı dikkatle görmek hızlı bir sayı yarışından daha değerlidir.','Accessible tombs and general-ticket coverage can change. Read the current list and budget special admissions separately. Heat, queues and narrow chambers favour a thoughtful choice of a few tombs rather than a numbers race.','Las tumbas accesibles y la entrada general pueden cambiar. Consulta la lista y presupuesta accesos especiales aparte. Calor, colas y pasos estrechos favorecen visitar pocas tumbas con atención.')},
 {name:l('Hatşepsut Tapınağı ve Luksor Tapınağı','Hatshepsut Temple and Luxor Temple','Templo de Hatshepsut y templo de Luxor'),area:l('İki ayrı Nil yakası','Opposite Nile banks','Orillas distintas del Nilo'),known:l('Teraslı tapınak ve şehir tapınağı','Terraced temple and city sanctuary','Templo aterrazado y santuario urbano'),reason:l('İki farklı tapınak yerleşimini karşılaştırmak için.','To compare two distinct temple settings.','Para comparar dos emplazamientos diferentes.'),tip:l('Bu iki durağı yakın komşu sanmayın.','These are not neighbouring stops.','No son paradas contiguas.'),body:l('Hatşepsut’un teraslı tapınağını Krallar Vadisi günüyle birleştirin. Luksor Tapınağı doğu merkezindedir; güncel akşam ziyareti varsa ışık değişimini izleyebilirsiniz. Aynı kartta anılmaları aynı alanda oldukları anlamına gelmez; ulaşımı yaka bazında kurun.','Pair Hatshepsut’s terraced temple with your Valley of the Kings day. Luxor Temple is in the east-bank centre and can offer evening light if current hours allow. Group the two visits by riverbank, not by name association.','Combina las terrazas de Hatshepsut con el día del Valle de los Reyes. El templo de Luxor está en el centro oriental y permite apreciar otra luz si su horario actual ofrece visita nocturna.')}
 ],stay:l('Doğu yaka merkez otel, restoran ve tapınak erişimi için; batı yaka daha sakin konaklama ve erken mezar ziyareti için uygundur. Sessizlik isteyenler odanın nehre bakması kadar cadde sesini, feribot ve gece dönüşünü de kontrol etmeli.','The east-bank centre suits hotels, dining and temple access; the west bank offers quieter stays near the tomb circuit. Check street noise, ferry access and evening returns rather than judging solely by a Nile view.','El centro oriental facilita hoteles, comidas y templos; la orilla oeste ofrece calma y proximidad a tumbas. Revisa ruido, ferry y regreso nocturno además de las vistas al Nilo.'),food:l('Ful, taameya, sebze yemekleri ve ızgaralar Nil gezisinde kolay seçeneklerdir. Turun öğle yemeği dahilse restoranı, içeceği ve özel beslenme uyarlamasını sorun. Erken ziyaret öncesi kahvaltı veya paket öğün için otelle bir gün önce anlaşın.','Ful, taameya, vegetable dishes and grills are accessible options. For included tour lunches, ask about restaurant, drinks and dietary adaptation. Arrange an early breakfast or packed meal with the hotel the day before your monument visit.','Ful, taameya, verduras y parrillas son opciones sencillas. Si el tour incluye comida, pregunta por restaurante, bebidas y adaptación de dieta. Acuerda el desayuno temprano con el hotel el día anterior.'),season:l('Ekim–nisan açık anıtlar için daha rahattır. Yazın batı yakasına çok erken başlayıp uzun öğle molası verin. Balon uçuşu ve Nil teknesi hava koşuluna bağlıdır; sabit saatli uçuş veya trenle dar bağlantı kurmayın.','October to April is more comfortable for exposed monuments. In summer, start the west bank very early and take a long midday break. Balloon flights and river outings depend on weather; avoid tight onward connections.','De octubre a abril se visitan mejor los monumentos expuestos. En verano empieza muy temprano y descansa al mediodía. Globos y barcos dependen del tiempo; evita enlaces ajustados con tren o avión.'),budget:l('Ana anıtlar, özel mezarlar, rehber, yaka transferi ve tekne ayrı masraflardır. Balonu temel ziyaret yerine bütçe eklemesi sayın; reklam fiyatıyla son toplamın aynı olduğundan ve iptal koşulundan emin olun.','Budget separately for main sites, special tombs, guides, riverbank transfers and boats. Treat a balloon ride as an extra and verify the final total and cancellation terms.','Separa monumentos, tumbas especiales, guía, traslados y barcos. Considera el globo un extra y confirma precio final y condiciones de cancelación.'),beyond:l('Hurgada karadan devam edilebilen Kızıldeniz ayağıdır; transfer gününe tekne turu koymayın. Dendera gibi başka anıtı eklemek için üçüncü gün bırakın; iki yakayı bir günde bitirmeye çalışarak boş gün üretmeyin.','Hurghada is a Red Sea extension reachable by road; do not book a boat outing on transfer day. Leave a third day for another monument such as Dendera instead of compressing both banks into one.','Hurghada permite continuar por carretera al mar Rojo; no reserves barco el día del traslado. Para otro monumento, como Dendera, deja una tercera jornada sin comprimir las dos orillas.'),itinerary:[[l('1. Gün — Batı yaka','Day 1 — West bank','Día 1 — Orilla oeste'),l('Erken Krallar Vadisi ziyareti','Early Valley of the Kings visit','Valle de los Reyes temprano'),l('Hatşepsut ve öğle dinlenmesi','Hatshepsut and midday rest','Hatshepsut y descanso al mediodía'),l('Nil kıyısında sakin yemek','A quiet meal beside the Nile','Cena tranquila junto al Nilo')],[l('2. Gün — Doğu yaka','Day 2 — East bank','Día 2 — Orilla este'),l("Karnak Tapınak Kompleksi","Karnak Temple Complex","Complejo de templos de Karnak"),l('Luxor Museum veya dinlenme','Luxor Museum or rest','Museo de Luxor o descanso'),l('Saatler uygunsa Luksor Tapınağı','Luxor Temple if opening hours allow','Templo de Luxor si el horario lo permite')]],tips:[[l('Mezar kapsamı','Tomb coverage','Tumbas incluidas'),l('Bilette kaç ve hangi mezarın dahil olduğunu satın almadan kontrol edin.','Check how many tombs and which ones your admission includes before buying.','Comprueba cuántas tumbas y cuáles incluye la entrada antes de comprarla.')],[l('Nehri geçmek başlangıçtır','A river crossing is only the start','Cruzar el río es solo el inicio'),l('Feribot sonrasında anıta giden ulaşımı ve dönüşü ayrıca planlayın.','Plan transport from the ferry landing to the sites and back.','Planifica el trayecto desde el embarcadero a los recintos y el regreso.')]],faqs:[[l('Luksor kaç günde gezilir?','How many days do you need in Luxor?','¿Cuántos días dedicar a Luxor?'),l('İki yakaya iki tam gün; müze ve daha sakin tempo için üç gün bırakın.','Allow two full days for the two banks, or three with museums and a slower pace.','Dos días completos para ambas orillas; tres con museos y un ritmo más tranquilo.')],[l('Hurgada’dan Luksor günübirlik mantıklı mı?','Is a Luxor day trip from Hurghada worthwhile?','¿Conviene visitar Luxor en un día desde Hurghada?'),l('Az zamanı olanlar için seçenek; uzun yol ve sıcaklık yorar. Tarih önceliğinde Luksor’da iki gece daha rahat olur.','It is an option with limited time, but the long road journey and heat are tiring. Two nights in Luxor suit a history-focused trip better.','Es una opción con poco tiempo, pero carretera y calor cansan. Si priorizas historia, dos noches en Luxor funcionan mejor.')],[l('Krallar Vadisi bileti her mezarı kapsar mı?','Does a Valley of the Kings ticket cover every tomb?','¿La entrada del Valle de los Reyes incluye todas las tumbas?'),l('Hayır. Genel kapsamı, açık mezarları ve özel girişleri güncel resmî bilet bilgisinden kontrol edin.','No. Check current general-ticket coverage, open tombs and separately charged entries through official ticket information.','No. Consulta tumbas abiertas, cobertura general y accesos de pago adicional en la información oficial vigente.')]],diet:l('Tur öğünündeki sebze veya pilav et suyuyla yapılabilir; vegan tercihi rezervasyonda ve masada tekrar belirtin. Helal tercihte et tedarikini sorun. Yeterli güncel doğrulama bulunmadığı için isimli restoran önerisi eklenmiyor.','Tour vegetables or rice may use meat stock; state vegan needs when booking and again at the table. Ask about meat sourcing for halal preferences. No named restaurant is recommended without sufficient current verification.','Verduras y arroz del tour pueden llevar caldo de carne; indica la dieta vegana al reservar y en la mesa. Para halal pregunta por el suministro. No se recomienda restaurante sin verificación actual suficiente.'),sources:[[tourism,'https://www.experienceegypt.eg/en/city/22/luxor-'],[l('Experience Egypt — doğu yaka','Experience Egypt — east bank','Experience Egypt — orilla este'),'https://www.experienceegypt.eg/en/Attraction-Details/299/east-bank'],[l('UNESCO — Antik Teb ve nekropolü','UNESCO — Ancient Thebes with its Necropolis','UNESCO — Antigua Tebas y su necrópolis'),'https://whc.unesco.org/en/list/87/']]
},
{
 code:'EG',name:l('Hurgada','Hurghada','Hurghada'),image:'/images/added-hurgada.avif',card:l('Giftun tekne gezileri, marina, El Dahar ve Kızıldeniz’de doğru otel kıyısını seçme rehberi.','Giftun boat trips, the marina, El Dahar and choosing the right Red Sea hotel coastline.','Barcos a Giftun, marina, El Dahar y consejos para elegir la costa adecuada del hotel.'),title:l('Hurgada Gezi Rehberi: Giftun, Plajlar ve Nerede Kalınır','Hurghada Travel Guide: Giftun, Beaches and Where to Stay','Qué hacer en Hurghada: Giftun, playas y dónde dormir'),meta:l('Hurgada gezi rehberi: Giftun Adaları, marina ve El Dahar; plaj oteli seçimi, tekne ve şnorkel turları, ulaşım, yemek ve Luksor bağlantısı.','Plan Hurghada with Giftun boat trips, marina walks and El Dahar, plus beach hotel choices, snorkelling, transfers, food and a Luxor extension.','Qué hacer en Hurghada: islas Giftun, marina y El Dahar, con hoteles de playa, excursiones de esnórquel, traslados, comida y conexión con Luxor.'),lede:l('Hurgada’da tatilin karakterini şehir adı değil otelinizin kıyısı belirler. Merkez yürüyüşü, sığ plaj, resif erişimi ve tekne çıkışı aynı yerde bulunmayabilir; rezervasyonu deniz beklentinize göre seçin.','In Hurghada, your hotel’s stretch of coast shapes the holiday more than the city name. Town walks, shallow beaches, reef access and boat departures may be in different places, so book around the water experience you want.','En Hurghada, la costa de tu hotel define las vacaciones. Paseos urbanos, playa poco profunda, arrecife y embarcadero pueden estar en lugares distintos: reserva según la experiencia marina que buscas.'),days:l('3–5 gece','3–5 nights','3–5 noches'),time:l('İlkbahar ve sonbahar','Spring and autumn','Primavera y otoño'),transport:l('Otel transferi ve sınırlı merkez yürüyüşü','Hotel transfers and short town walks','Traslados de hotel y paseos urbanos cortos'),arrival:l('Hurghada International (HRG) transferini otelin tam konumuyla ayırın. El Gouna, Makadi Bay ve Soma Bay merkez Hurgada ile aynı kısa yol değildir. Luksor’dan gelişte yol süresi ve dinlenme payını ekleyin; aynı öğleden sonraya tekne rezervasyonu koymayın.','Book your Hurghada International (HRG) transfer with the hotel’s exact location. El Gouna, Makadi Bay and Soma Bay are not the same short central journey. From Luxor, leave travel and rest time rather than booking a same-afternoon boat.','Reserva desde Hurghada International (HRG) con la ubicación exacta del hotel. El Gouna, Makadi Bay y Soma Bay no equivalen al centro. Desde Luxor, deja tiempo de carretera y descanso antes de una salida en barco.'),movement:l('Merkezde marina ve bazı çarşı sokakları yürünebilir; kıyı otelleri arasında araç gerekir. Turun otelden alma alanını ve ek transfer ücretini sorun. Özel araçta toplam fiyat, bekleme ve dönüşü netleştirin; uzak resort gününü şehir merkezine gidip gelerek bölmeyin.','The marina and some market streets are walkable, but coastal resorts need transport. Ask whether a tour’s pickup zone includes your hotel and if extra transfer fees apply. Agree a private car’s total price, waiting and return before departure.','Marina y algunas calles comerciales se recorren a pie; entre resorts hace falta transporte. Comprueba si el tour recoge en tu hotel y cobra suplemento. Acuerda precio total, esperas y regreso del coche privado.'),overview:l('Bir merkez yürüyüşü, bir Giftun günü ve esnek plaj zamanı çoğu ilk geziyi dengeler. Deniz durumuna bağlı turu tatilin son saatine koymadan alternatif gün bırakın.','A town walk, a Giftun day and flexible beach time suit a first stay. Keep an alternative day for weather-dependent trips rather than using the final hours of your holiday.','Un paseo urbano, un día en Giftun y playa flexible equilibran la primera estancia. Deja un día alternativo para salidas sujetas al mar, sin apurarlas al final.'),sights:[
 {name:l('Giftun Adaları','Giftun Islands','Islas Giftun'),area:l('Hurgada açıkları','Off Hurghada','Frente a Hurghada'),known:l('Tekne, plaj ve şnorkel','Boats, beaches and snorkelling','Barcos, playas y esnórquel'),reason:l('Kızıldeniz’i kıyı otelinin ötesinde görmek için.','For a Red Sea day beyond the hotel beach.','Para conocer el mar Rojo más allá del hotel.'),tip:l('Ada, plaj paketi ve koruma alanı ücretini ayırın.','Distinguish the island, beach package and protected-area fees.','Distingue isla, paquete de playa y tasas de protección.'),body:l('Giftun paketleri aynı gezi değildir: kullanılan plaj, teknede süre, şnorkel durakları ve öğün değişir. Koruma alanı ücretinin ve ekipmanın dahil olduğunu teyit edin. Mercana basmayın; can yeleği ve yüzme düzeyinizi operatörle paylaşın.','Giftun packages differ by beach, boat time, snorkel stops and meals. Confirm protected-area fees and equipment. Avoid standing on coral and discuss flotation and your swimming ability with the operator.','Los paquetes de Giftun varían en playa, horas de barco, paradas y comida. Confirma tasas y equipo. No pises coral y comunica al operador tu nivel de natación y necesidades de flotación.')},
 {name:l('Hurgada Marina','Hurghada Marina','Marina de Hurghada'),area:l('Sakkala kıyısı','Sakkala waterfront','Costa de Sakkala'),known:l('Liman yürüyüşü ve restoranlar','Harbour walks and restaurants','Paseo portuario y restaurantes'),reason:l('Deniz gününden sonra merkezde kısa bir akşam için.','For a short town evening after a day at sea.','Para una tarde urbana breve tras el mar.'),tip:l('Otelle dönüş transferini önceden belirleyin.','Arrange the return transfer to your hotel.','Organiza el regreso al hotel.'),body:l('Marina kontrollü ve restoran ağırlıklı bir yürüyüş alanıdır; bütün Hurgada’yı temsil etmez. Yemekte balık ağırlığı, hazırlama ücreti ve içecekleri son toplam üzerinden karşılaştırın. Uzaktaki otelden gelecekseniz kısa yürüyüş için uzun dönüş maliyetini değerlendirin.','The marina is a managed, restaurant-led waterfront rather than a portrait of all Hurghada. Compare final meal totals, including fish weight, preparation and drinks, and weigh the transfer cost if your hotel is far away.','Marina es un paseo acondicionado con restaurantes, no toda Hurghada. Compara precio final, peso del pescado, preparación y bebidas; valora el traslado si el hotel queda lejos.')},
 {name:l('El Dahar','El Dahar','El Dahar'),area:l('Eski merkez','Old town centre','Centro antiguo'),known:l('Yerel pazar ve gündelik sokaklar','Local markets and everyday streets','Mercados y calles cotidianas'),reason:l('Resort dışındaki şehir yaşamını tanımak için.','For everyday town life beyond the resorts.','Para conocer la vida urbana fuera de los resorts.'),tip:l('Alışverişte fiyatı ve para birimini netleştirin.','Clarify price and currency when shopping.','Aclara precio y moneda al comprar.'),body:l('El Dahar’da kısa pazar yürüyüşü ve yerel yemek molası planlayın. Alışverişi tek başına zorunlu bir tur durağına çevirmeyin; ilgilenmediğiniz satış teklifini nazikçe reddedin. Merkezdeki anıt ziyaretinde kıyafet ve fotoğraf kurallarını sorun.','Plan a short market walk and local meal in El Dahar. Shopping need not become a compulsory tour stop; decline unwanted offers politely. Ask about clothing and photography when entering religious landmarks.','Planea un paseo por el mercado y una comida local en El Dahar. Comprar no tiene que convertirse en parada obligatoria; rechaza ofertas con cortesía. Consulta vestimenta y fotos en espacios religiosos.')}
 ],stay:l('Sakkala merkez ve marina, El Dahar yerel şehir dokusu, kıyı resortları plaj önceliği içindir. Otelin “özel plaj” ifadesi kumdan kolay giriş veya resif garantisi değildir. Güncel plaj fotoğrafı, iskele, sığlık, rüzgâr ve çocuklar için giriş koşulunu kontrol edin.','Sakkala suits marina access, El Dahar everyday town life, and coastal resorts beach-focused stays. “Private beach” does not guarantee sandy entry or a house reef: inspect beach photos, jetties, shallows and suitability for children.','Sakkala facilita marina; El Dahar, vida local; resorts costeros, playa. “Playa privada” no garantiza entrada de arena ni arrecife: revisa fotos, muelles, profundidad y acceso para niños.'),food:l('Deniz ürünleri kıyı gezisinde öne çıkar; ful, taameya ve koşeri daha gündelik alternatiflerdir. Her şey dahil otelde restoran saatlerini, alakart rezervasyonunu ve özel beslenme koşulunu okuyun. Taze balık siparişinde kilo ile porsiyon fiyatını karıştırmayın.','Seafood features strongly, with ful, taameya and koshary as everyday alternatives. At all-inclusive hotels, check restaurant hours, à-la-carte bookings and dietary arrangements. For fresh fish, distinguish a per-kilo quote from a portion price.','El pescado destaca, con ful, taameya y koshari como alternativas cotidianas. En todo incluido revisa horarios, reservas a la carta y adaptación de dieta. Distingue precio por kilo y por ración.'),season:l('İlkbahar ve sonbahar deniz ile şehir gezisini birleştirmek için dengelidir. Kışın hava güneşli olsa da rüzgâr ve su sıcaklığı deneyimi değiştirir. Yaz sıcağında korumasız öğle yürüyüşünü azaltın; tekne günü için güncel deniz koşulunu izleyin.','Spring and autumn balance water activities and town visits. Winter sunshine does not remove wind or cooler-water considerations. Reduce exposed midday walking in summer and check sea conditions for boat days.','Primavera y otoño equilibran mar y ciudad. Sol en invierno no elimina viento ni agua fresca. Reduce paseos expuestos al mediodía en verano y consulta el estado del mar para los barcos.'),budget:l('Oda paketine transfer, deniz turu, dalış ekipmanı, koruma alanı ücreti ve özel öğünleri ekleyin. Ucuz tekne fiyatında teknenin kapasitesi, plajda kalan süre ve iptal şartı daha önemli olabilir.','Add transfers, boat trips, diving equipment, protected-area fees and special meals to the room package. For cheaper boats, compare capacity, beach time and cancellation terms rather than price alone.','Añade traslados, barcos, equipo, tasas y comidas especiales al paquete de hotel. En un barco barato compara capacidad, tiempo de playa y cancelación, además del precio.'),beyond:l('Luksor güçlü tarih devamıdır; mümkünse iki geceyle iki Nil yakasını görün. El Gouna ise kuzeyde ayrı bir kıyı yerleşimidir. Hurgada ve Şarm el-Şeyh’i aynı sahil yolunun komşuları sanmayın; aralarındaki geçişi ayrıca planlayın.','Luxor makes a strong history extension, ideally with two nights for both Nile banks. El Gouna is a separate coastal base to the north. Hurghada and Sharm are not neighbours on one continuous coastal road.','Luxor amplía el viaje con historia, mejor dos noches para ambas orillas. El Gouna es otra base al norte. Hurghada y Sharm no son vecinos en una misma carretera costera.'),itinerary:[[l('1. Gün — Kıyı ve merkez','Day 1 — Coast and town','Día 1 — Costa y ciudad'),l('Otel plajını ve giriş koşulunu tanıyın','Explore your hotel beach and access','Conoce la playa y acceso del hotel'),l('El Dahar’da kısa gezi','A short El Dahar visit','Visita breve a El Dahar'),l('Marinada yemek ve otele dönüş','Marina dinner and return to the hotel','Cena en marina y regreso al hotel')],[l('2. Gün — Giftun','Day 2 — Giftun','Día 2 — Giftun'),l('Tekneyle ada ve şnorkel programı','Boat departure for island and snorkel visits','Barco para isla y esnórquel'),l('Paket kapsamına göre plaj molası','Beach time according to your package','Playa según el paquete contratado'),l('Dinlenme; başka uzun transfer eklemeyin','Rest without another long transfer','Descanso sin añadir otro traslado largo')],[l('3. Gün — Esnek deniz günü','Day 3 — Flexible water day','Día 3 — Mar flexible'),l('Havaya göre plaj veya dalış','Beach or diving as conditions allow','Playa o buceo según condiciones'),l('Serbest zaman ve gölgede mola','Free time and a shaded break','Tiempo libre y descanso a la sombra'),l('Yerel yemek veya otelde sakin akşam','Local meal or a quiet hotel evening','Comida local o tarde tranquila en hotel')]],tips:[[l('Plaj erişimini okuyun','Read the beach details','Revisa el acceso a la playa'),l('Kum fotoğrafı resife kolay erişim demek değildir; otelin gerçek deniz girişini sorun.','A sandy beach photo does not establish easy reef entry; ask about actual access.','Una foto de arena no demuestra acceso fácil al arrecife; pregunta por la entrada real.')],[l('Canlılara mesafe','Keep wildlife space','Respeta a la fauna'),l('Teknede deniz canlılarını besleyen veya takip ederek sıkıştıran uygulamayı tercih etmeyin.','Avoid excursions that feed or crowd marine wildlife.','Evita excursiones que alimenten o acorralen fauna marina.')]],faqs:[[l('Hurgada kaç gün için uygun?','How long should you stay in Hurghada?','¿Cuánto tiempo quedarse en Hurghada?'),l('Bir tekne günü ve dinlenme için üç veya dört gece; dalış ya da Luksor eklemek için daha uzun süre.','Three or four nights suit one boat day and rest; allow longer for diving or a Luxor extension.','Tres o cuatro noches para barco y descanso; más si añades buceo o Luxor.')],[l('Giftun turu seçerken neye bakmalı?','What should you compare in a Giftun trip?','¿Qué comparar al reservar Giftun?'),l('Kullanılan plaj, tekne kapasitesi, şnorkel durakları, ekipman, öğün, alan ücreti ve otel transferi.','Beach, boat capacity, snorkel stops, equipment, meals, protected-area fees and hotel pickup.','Playa, capacidad, paradas de esnórquel, equipo, comida, tasas y recogida en hotel.')],[l('Hurgada mı Şarm el-Şeyh mi?','Hurghada or Sharm el-Sheikh?','¿Hurghada o Sharm el-Sheij?'),l('Luksor’la karadan bağlanan tatil için Hurgada; Sina kıyısı ve Ras Muhammad odağı için Şarm. Otelin resif ve plaj erişimini iki yerde de kontrol edin.','Hurghada pairs with Luxor by road; Sharm suits Sinai and Ras Muhammad. Check the individual hotel’s beach and reef access in either.','Hurghada combina por carretera con Luxor; Sharm, con Sinaí y Ras Muhammad. En ambos revisa playa y arrecife del hotel.')]],diet:l('Her şey dahil büfede vegan etiketi yalnız sebze görünümüne dayanmaz; et suyu, tereyağı ve ortak servis ekipmanını sorun. Helal tercihte et kaynağını otelle teyit edin. Güncel kanıt olmadan isimli restoran kartı eklenmiyor.','An all-inclusive buffet dish is not vegan merely because it looks vegetable-based; ask about stock, butter and shared serving equipment. Confirm meat sourcing with the hotel for halal preferences. No restaurant is named without current evidence.','Una verdura de bufé no es vegana solo por su aspecto; pregunta por caldo, mantequilla y utensilios compartidos. Para halal confirma el suministro con el hotel. No se nombra restaurante sin evidencia actual.'),sources:[[tourism,'https://www.experienceegypt.eg/en/city/23/hurghada-'],[l('Experience Egypt — Giftun ada gezileri','Experience Egypt — Giftun island trips','Experience Egypt — excursiones a Giftun'),'https://www.experienceegypt.eg/en/attraction-details/152/island-life'],[l('Experience Egypt — Kızıldeniz kıyısı','Experience Egypt — Red Sea coast','Experience Egypt — costa del mar Rojo'),'https://www.experienceegypt.eg/en/attraction/19/sun-sea']]
},
{
 code:'EG',name:l('Şarm el-Şeyh','Sharm el-Sheikh','Sharm el-Sheij'),image:'/images/added-sarm-el-seyh.avif',card:l('Ras Muhammad, Naama Bay, Eski Çarşı ve resif erişimine göre konaklama seçilen Sina kıyısı.','Ras Muhammad, Naama Bay, the Old Market and Sinai hotels chosen around reef access.','Ras Muhammad, Naama Bay, Mercado Viejo y hoteles del Sinaí elegidos por acceso al arrecife.'),title:l('Şarm el-Şeyh Gezi Rehberi: Resifler ve Otel Bölgeleri','Sharm el-Sheikh Guide: Reefs, Ras Muhammad and Hotels','Sharm el-Sheij: arrecifes, Ras Muhammad y alojamiento'),meta:l('Şarm el-Şeyh gezi rehberi: Ras Muhammad, Naama Bay ve Eski Çarşı; resif erişimi, otel bölgesi seçimi, dalış, şnorkel ve ulaşım önerileri.','Plan Sharm el-Sheikh with Ras Muhammad, Naama Bay and the Old Market, plus reef access, hotel areas, diving, snorkelling and practical transfers.','Organiza Sharm el-Sheij con Ras Muhammad, Naama Bay y el Mercado Viejo: arrecifes, zonas de hotel, buceo, esnórquel y consejos de transporte.'),lede:l('Şarm el-Şeyh geniş bir kıyı destinasyonudur: Naama Bay’in yürüyüşü, Sharks Bay’in otelleri ve Nabq’ın kıyısı aynı deneyimi sunmaz. Tatili otel yıldızından önce denize nasıl gireceğiniz ve hangi bölgede kalacağınız üzerinden kurun.','Sharm el-Sheikh spreads across distinct bays. Naama’s walks, Sharks Bay’s hotels and Nabq’s coastline offer different stays: choose how you want to enter the sea and where you want to spend evenings before comparing hotel stars.','Sharm el-Sheij se extiende por bahías distintas. Naama, Sharks Bay y Nabq ofrecen estancias diferentes: elige primero cómo acceder al mar y dónde pasar las tardes, después compara estrellas del hotel.'),days:l('4–5 gece','4–5 nights','4–5 noches'),time:l('İlkbahar ve sonbahar','Spring and autumn','Primavera y otoño'),transport:l('Otel ve tur transferleri','Hotel and excursion transfers','Traslados de hotel y excursión'),arrival:l('Sharm el-Sheikh International (SSH) transferinde otelin Naama Bay, Sharks Bay veya Nabq konumunu belirtin. Varış izninin planladığınız tüm gezileri kapsadığını uçuş öncesinde resmî kanaldan doğrulayın; yalnız kıyı tatiline ait koşulu başka şehre taşımayın.','For Sharm el-Sheikh International (SSH), specify whether the hotel is in Naama Bay, Sharks Bay or Nabq. Confirm that your entry permission covers every planned excursion rather than assuming a coastal-stay arrangement applies elsewhere.','En el traslado desde Sharm el-Sheikh International (SSH), indica Naama Bay, Sharks Bay o Nabq. Comprueba oficialmente que tu permiso de entrada cubra todas las excursiones; no extrapoles condiciones de una estancia costera.'),movement:l('Otel koyları arasında mesafe vardır; Naama’da yürüyüş yapılabilmesi bütün destinasyonun yürünebilir olduğu anlamına gelmez. Tur transferinde iskele, kalkış saati ve otelden alma kapsamını kontrol edin. Akşam çarşı gezisinde dönüşü de içeren fiyatı baştan netleştirin.','Distances separate the hotel bays; a walkable Naama stay does not make the whole destination walkable. Confirm pier, departure time and hotel pickup coverage for excursions, and agree return transport for an Old Market evening.','Los hoteles de distintas bahías están separados. Que Naama sea paseable no vuelve caminable todo el destino. Confirma muelle, salida y recogida del tour, y acuerda regreso para la visita al Mercado Viejo.'),overview:l('Deniz gününü kıyı yürüyüşünden ayırın. Ras Muhammad gezisini hava için yedek günü olacak şekilde planlayıp Naama ve Eski Çarşı’yı iki kısa akşam programına dönüştürebilirsiniz.','Separate a marine excursion from town walking. Schedule Ras Muhammad with a spare weather day and use Naama and the Old Market for two shorter evening outings.','Separa la excursión marina de los paseos urbanos. Deja un día alternativo para Ras Muhammad y dedica tardes breves a Naama y Mercado Viejo.'),sights:[
 {name:l('Ras Muhammad','Ras Muhammad','Ras Muhammad'),area:l('Sina yarımadasının ucu','Tip of the Sinai Peninsula','Extremo de la península del Sinaí'),known:l('Koruma alanı ve resifler','Protected area and reefs','Espacio protegido y arrecifes'),reason:l('Deniz yaşamını koruma kuralları içinde görmek için.','For marine life within a protected-area visit.','Para observar vida marina en un espacio protegido.'),tip:l('Kara veya tekne programını, alan ücretini ve ekipmanı ayırın.','Check whether the trip is by land or boat, with fees and equipment.','Distingue excursión terrestre o en barco, tasas y equipo.'),body:l('Ras Muhammad kara ziyareti ve tekne dalış/şnorkel günü farklı programlardır. Yüzme düzeyinizi ve beklediğiniz durakları operatöre söyleyin; rehber, ekipman ve koruma alanı ücretini kontrol edin. Resife dokunmadan ve canlıları beslemeden gözlem yapın.','A land visit to Ras Muhammad differs from a boat diving or snorkel day. Tell the operator your swimming ability and desired stops; check guiding, equipment and protected-area fees. Observe without touching coral or feeding animals.','Una visita terrestre a Ras Muhammad difiere del barco de buceo o esnórquel. Comunica nivel de natación y paradas deseadas; revisa guía, equipo y tasas. Observa sin tocar coral ni alimentar animales.')},
 {name:l('Naama Bay','Naama Bay','Naama Bay'),area:l('Naama koyu','Naama bay area','Bahía de Naama'),known:l('Sahil ve akşam yürüyüşü','Beach and evening walks','Playa y paseos al atardecer'),reason:l('Otel tatiline yürünebilir akşam bölgesi eklemek için.','For a walkable evening area alongside a resort stay.','Para añadir una zona de tarde paseable al resort.'),tip:l('Otelin gerçekten yürüyüş alanına yakınlığını kontrol edin.','Check the hotel’s actual distance to the walking area.','Comprueba la distancia real del hotel al paseo.'),body:l('Naama’da restoran ve sahil yürüyüşü daha yoğun bir akşam ritmi sunar. Koydaki her otelin plajı ve gürültü düzeyi aynı değildir. Merkezde kalmak isteyenler oda konumunu, sahile geçişi ve tekne turu toplama saatini birlikte değerlendirmeli.','Naama offers a busier restaurant and seafront evening. Hotels differ in beach access and noise; check room location, access to the water and excursion pickup timing rather than judging solely by the bay name.','Naama ofrece más movimiento de restaurantes y paseo marítimo. Hoteles y ruido varían: revisa habitación, acceso al agua y hora de recogida de excursiones, no solo el nombre de la bahía.')},
 {name:l('Eski Çarşı','Old Market','Mercado Viejo'),area:l('Sharm El Maya çevresi','Sharm El Maya area','Zona de Sharm El Maya'),known:l('Çarşı ve yerel akşam','Market streets and evening dining','Mercado y cenas locales'),reason:l('Resort dışında kısa şehir molası için.','For a brief town visit beyond the resort.','Para una visita urbana breve fuera del resort.'),tip:l('Alışveriş ve araç dönüş fiyatını önceden konuşun.','Agree shopping and return transport prices clearly.','Aclara compras y transporte de vuelta.'),body:l('Eski Çarşı’da alışveriş kadar yemek molasına da zaman bırakın. Al Sahaba Camii çevresinde ziyaret ve fotoğraf kuralına uyun. Uzak koydaki otelden gelirken gidiş-dönüş maliyetini ve bekleme şartını tek paketin içinde netleştirin.','Leave room for a meal as well as browsing. Respect access and photography rules around Al Sahaba Mosque. From a distant bay, clarify round-trip cost and waiting arrangements in the same agreement.','Deja tiempo para comer además de comprar. Respeta acceso y fotos en torno a la mezquita Al Sahaba. Desde una bahía distante, acuerda coste de ida y vuelta y esperas en el mismo contrato.')}
 ],stay:l('Naama yürüyüş ve akşam hareketi, Sharks Bay resif odaklı oteller, Nabq daha geniş resort alanları sunar. Bunlar genel yönlendirmedir: gerçek otel plajında iskele, derin su, rüzgâr, yüzme alanı ve çocuk erişimini ayrı kontrol edin.','Naama suits evening walks, Sharks Bay reef-focused hotels, and Nabq larger resort settings. These are broad pointers: inspect each hotel’s jetty, deep-water entry, wind exposure and suitability for children.','Naama favorece paseos, Sharks Bay hoteles orientados al arrecife y Nabq resorts amplios. Son pautas generales: revisa muelle, profundidad, viento y acceso infantil de cada hotel.'),food:l('Balık ve ızgara yanında ful, taameya ve sebze tabakları bulunur. Resort büfesini tek seçenek saymayın, fakat uzak koydan akşam yemeği için transfer bedelini ekleyin. Balıkta kilo fiyatı, hazırlama ve yan tabakları siparişten önce sorun.','Alongside fish and grills, look for ful, taameya and vegetable dishes. Resorts are not the only dining option, but add transfer costs from distant bays. Ask about fish weight, preparation and sides before ordering.','Además de pescado y parrilla, busca ful, taameya y verduras. Hay vida fuera del bufé, pero suma el traslado desde bahías lejanas. Pregunta por peso del pescado, preparación y guarniciones.'),season:l('İlkbahar ve sonbahar sıcaklık açısından dengelidir. Kışın rüzgâr ve serin su, yazın çok sıcak açık hava saatleri planı etkiler. Dalış veya şnorkel için deniz koşulunu güncel kontrol edin; iyi hava fotoğrafı her gün aynı erişimi garanti etmez.','Spring and autumn offer a balanced temperature window. Winter wind and cooler water, or summer heat, can shape the day. Check current sea conditions rather than relying on sunny promotional photos.','Primavera y otoño ofrecen temperaturas más equilibradas. Viento y agua fresca en invierno, o calor en verano, modifican el programa. Consulta el mar actual; una foto soleada no garantiza acceso diario.'),budget:l('Otel fiyatına dalış, şnorkel ekipmanı, koruma alanı, havaalanı ve koylar arası transferi ekleyin. Sertifikalı dalış ile tanıtım dalışı aynı ürün değildir; eğitim, rehber oranı ve dahil dalış sayısını karşılaştırın.','Add diving, snorkel equipment, protected-area access and airport or bay transfers to the hotel price. Certified dives and introductory dives are different products: compare training, guide ratios and included dives.','Añade buceo, equipo, tasas y traslados al hotel. Buceo certificado y bautismo son productos distintos: compara formación, proporción de guías e inmersiones incluidas.'),beyond:l('Kahire ayrı uçuşlu kültür ayağı olarak daha rahat işler. Dahab’ı eklemek istiyorsanız onu uzun bir tekne gününün devamına sıkıştırmayın. Her şehir dışı gezinin giriş belgenize, operatör koşullarına ve güncel rotaya uygunluğunu doğrulayın.','Cairo works better as a separate flight-based cultural leg. If adding Dahab, give it its own time rather than following a long boat day. Confirm each excursion’s compatibility with your documents and current operator conditions.','El Cairo funciona mejor como etapa cultural con vuelo. Si añades Dahab, dale tiempo propio. Confirma que cada excursión encaja con tus documentos, ruta actual y condiciones del operador.'),itinerary:[[l('1. Gün — Koyunuzu tanıyın','Day 1 — Explore your bay','Día 1 — Conoce tu bahía'),l('Otel plajı ve deniz girişini kontrol edin','Check the hotel beach and water access','Comprueba playa y acceso al agua'),l('Dinlenme ve tur koşullarını netleştirme','Rest and confirm excursion details','Descanso y confirmación de excursión'),l('Naama Bay’de yürüyüş','Naama Bay walk','Paseo por Naama Bay')],[l('2. Gün — Ras Muhammad','Day 2 — Ras Muhammad','Día 2 — Ras Muhammad'),l('Seçtiğiniz kara veya tekne programı','Your chosen land or boat excursion','Excursión terrestre o en barco elegida'),l('Koruma kurallarıyla deniz gezisi','Marine visit following conservation rules','Visita marina respetando conservación'),l('Otelde sakin akşam','A quiet hotel evening','Tarde tranquila en el hotel')],[l('3. Gün — Esnek kıyı günü','Day 3 — Flexible coastal day','Día 3 — Costa flexible'),l('Havaya göre resif veya plaj','Reef or beach as weather allows','Arrecife o playa según el tiempo'),l('Dinlenme ve serbest zaman','Rest and free time','Descanso y tiempo libre'),l('Eski Çarşı’da kısa gezi ve yemek','Short Old Market visit and meal','Visita breve y cena en Mercado Viejo')]],tips:[[l('İskele mi kum girişi mi?','Jetty or sandy entry?','¿Muelle o entrada de arena?'),l('Resif otelini seçmeden çocuk, yüzme seviyesi ve dalga koşuluna uygun deniz girişini öğrenin.','Before booking a reef hotel, check water entry against children’s needs, swimming ability and wave conditions.','Antes de reservar hotel de arrecife, revisa entrada al agua según niños, nivel de natación y oleaje.')],[l('Deniz günü esnek kalsın','Keep a flexible sea day','Deja flexible el día de mar'),l('Hava nedeniyle değişen tur için son güne kalmadan yedek gün bırakın.','Leave a backup day for weather changes before your final day.','Deja una jornada alternativa por cambios de tiempo antes del último día.')]],faqs:[[l('Şarm el-Şeyh kaç gün için uygun?','How long should you stay in Sharm el-Sheikh?','¿Cuánto quedarse en Sharm el-Sheij?'),l('Bir deniz turu ve dinlenme için dört veya beş gece; çok sayıda dalış için daha uzun süre.','Four or five nights allow a marine excursion and rest; stay longer for multiple diving days.','Cuatro o cinco noches para excursión marina y descanso; más para varios días de buceo.')],[l('Naama Bay mi Nabq mı?','Naama Bay or Nabq?','¿Naama Bay o Nabq?'),l('Akşam yürüyüşü için Naama; resort odağı için Nabq. Her otelde gerçek plaj, rüzgâr ve resif erişimi ayrı değerlendirilmelidir.','Naama for evening walks, Nabq for a resort-focused stay. Check beach, wind and reef access at the individual hotel.','Naama para paseos; Nabq para estancia de resort. Revisa playa, viento y acceso al arrecife de cada hotel.')],[l('Ras Muhammad için dalış bilmek şart mı?','Do you need diving skills for Ras Muhammad?','¿Hay que saber bucear para visitar Ras Muhammad?'),l('Hayır; kara ve şnorkel programları da bulunur. Yüzme düzeyi ve erişim koşuluna uygun ürünü yetkili işletmeden seçin.','No: land and snorkelling programmes are also available. Choose a licensed operator’s trip suited to your swimming ability and access needs.','No; hay visitas terrestres y esnórquel. Elige con un operador autorizado la opción adecuada a tu natación y necesidades de acceso.')]],diet:l('Otelde vegan öğün için et suyu, tereyağı, yoğurt ve ortak pişirmeyi netleştirin. Helal tercihte yalnız büfe etiketini değil tedariki ve mutfak uygulamasını sorun. Yeterli güncel doğrulama olmadan restoran adı önerilmiyor.','Clarify stock, butter, yogurt and shared cooking for vegan hotel meals. For halal preferences, ask about sourcing and kitchen practice rather than relying only on a buffet label. No restaurant is named without sufficient current verification.','Para dieta vegana aclara caldo, mantequilla, yogur y cocina compartida. Para halal pregunta por suministro y prácticas de cocina, además de la etiqueta del bufé. No se recomienda restaurante sin verificación actual.'),sources:[[tourism,'https://www.experienceegypt.eg/en/city/16/sharm-al-sheikh'],[l('Experience Egypt — resif ve dalış','Experience Egypt — reefs and diving','Experience Egypt — arrecifes y buceo'),'https://www.experienceegypt.eg/en/Attraction-Details/186/beaches-snorkeling-diving'],[l('Experience Egypt — doğal koruma alanları','Experience Egypt — natural protectorates','Experience Egypt — espacios naturales protegidos'),'https://www.experienceegypt.eg/en/attraction-details/436/natural-protectorates']]
}];
